      .next()
      .is_some_and(|token| token.kind == Identifier && token.lexeme() == Keyword::X.lexeme())
      && tokens.next().is_some_and(|token| token.kind == StringToken)
  }

  // Check if the next tokens are a format string, i.e., `f"foo"`.
  //
